"""Temporary exact-revision source resolution; removed from the candidate tree."""
from pathlib import Path
import re
import subprocess

main = "056952b5a3d625fd1d19384942d452114804380f"
runner = "src/review-orchestration/infrastructure/production-t0-review-runner.ts"
generated = ["action-dist/conflict-runtime.cjs", "dist/index.js", "dist/index.js.map", "dist/single-t0-plan.js"]
unmerged = subprocess.check_output(["git", "diff", "--name-only", "--diff-filter=U"], text=True).splitlines()
if set(unmerged) != set([runner, *generated]):
    raise RuntimeError("Unexpected conflict inventory; do not use a generic resolution")
text = Path(runner).read_text()
ordinal = [0]
def resolve(match):
    index = ordinal[0]
    ordinal[0] += 1
    ours, theirs = match[1], match[2]
    if index == 0:
        if "scopedModelInvocations" not in ours or "ReviewMemorySession" not in theirs:
            raise RuntimeError("Unexpected import conflict")
        return ours + theirs
    if index == 1:
        if ours.strip() != ": discoveryInvocations," or "memoryAdmission: reviewMemory," not in theirs:
            raise RuntimeError("Unexpected invocation composition conflict")
        return ours + "            memoryAdmission: reviewMemory,\n"
    raise RuntimeError("Unexpected additional source conflict")
text = re.sub(r"<<<<<<< HEAD\n(.*?)=======\n(.*?)>>>>>>> " + main + r"\n", resolve, text, flags=re.S)
if ordinal[0] != 2 or "<<<<<<<" in text:
    raise RuntimeError("Not all expected source conflicts were resolved")
Path(runner).write_text(text)
# dist/* is regenerated by npm run build. The wrapper is subsequently copied
# from the exact committed, rebuilt SaaS source through its existing sync tool.
subprocess.run(["git", "checkout", "--ours", "--", *generated], check=True)
subprocess.run(["git", "add", "--", runner, *generated], check=True)
if subprocess.check_output(["git", "ls-files", "-u"]):
    raise RuntimeError("Unresolved integration conflicts remain")
print("Retained scoped discovery, memory admission, and both native/Gateway composition paths.")
